import React, { useState, useEffect } from 'react';
import { getCategories, createCategory, updateCategory, deleteCategory } from '../services/api';
import toast from 'react-hot-toast';

function CategoryModal({ category, onSave, onClose }) {
  const [form, setForm] = useState({ name: category?.name || '', description: category?.description || '' });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (category) {
        await updateCategory(category.id, form);
        toast.success('Category updated!');
      } else {
        await createCategory(form);
        toast.success('Category created!');
      }
      onSave();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to save');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal" style={{ maxWidth: 420 }}>
        <div className="modal-header">
          <h3>{category ? '✏️ Edit Category' : '➕ New Category'}</h3>
          <button className="btn btn-ghost btn-icon" onClick={onClose}>✕</button>
        </div>
        <form onSubmit={handleSubmit}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            <div className="form-group">
              <label className="form-label">Category Name *</label>
              <input className="form-input" value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })} required placeholder="e.g. Fruits & Vegetables" />
            </div>
            <div className="form-group">
              <label className="form-label">Description</label>
              <textarea className="form-textarea" rows={3} value={form.description || ''}
                onChange={e => setForm({ ...form, description: e.target.value })}
                placeholder="Optional description" style={{ resize: 'vertical' }} />
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10, marginTop: 20 }}>
            <button type="button" className="btn btn-ghost" style={{ flex: 1 }} onClick={onClose}>Cancel</button>
            <button type="submit" className="btn btn-primary" style={{ flex: 2 }} disabled={loading}>
              {loading ? <span className="spinner" /> : (category ? 'Update' : 'Create Category')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

const CAT_EMOJIS = {
  'Fruits & Vegetables': '🥦', 'Dairy & Eggs': '🥛', 'Bakery': '🍞',
  'Beverages': '🥤', 'Snacks': '🍿', 'Grains & Pulses': '🌾',
  'Meat & Seafood': '🍗', 'Personal Care': '🧴', 'Household': '🧹',
  'Frozen Foods': '🧊',
};
const CAT_COLORS = [
  'var(--accent-dim)', 'var(--blue-dim)', 'var(--orange-dim)',
  'var(--purple-dim)', 'var(--red-dim)', 'var(--yellow-dim)',
];

export default function Categories() {
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(false);
  const [selected, setSelected] = useState(null);

  const fetchData = () => {
    setLoading(true);
    getCategories()
      .then(r => setCategories(r.data))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchData(); }, []);

  const handleDelete = async (cat) => {
    if (cat.product_count > 0) {
      toast.error(`Cannot delete: ${cat.product_count} products in this category`);
      return;
    }
    if (!window.confirm(`Delete "${cat.name}"?`)) return;
    try {
      await deleteCategory(cat.id);
      toast.success('Category deleted');
      fetchData();
    } catch {
      toast.error('Failed to delete category');
    }
  };

  return (
    <>
      <div className="page-header">
        <div className="flex items-center justify-between">
          <div>
            <h1>Categories</h1>
            <p>Organize your products into categories</p>
          </div>
          <button className="btn btn-primary" onClick={() => { setSelected(null); setModal(true); }}>
            + Add Category
          </button>
        </div>
      </div>

      <div className="page-content">
        {loading ? (
          <div className="page-loading"><div className="spinner" style={{ width: 32, height: 32 }} /></div>
        ) : (
          <>
            {/* Summary */}
            <div className="flex gap-16 mb-20">
              <div className="card" style={{ flex: 1, textAlign: 'center' }}>
                <div style={{ fontSize: 28, fontFamily: 'Inter', fontWeight: 800, color: 'var(--blue)' }}>{categories.length}</div>
                <div style={{ fontSize: 12, color: 'var(--text3)' }}>Total Categories</div>
              </div>
              <div className="card" style={{ flex: 1, textAlign: 'center' }}>
                <div style={{ fontSize: 28, fontFamily: 'Inter', fontWeight: 800, color: 'var(--accent)' }}>
                  {categories.reduce((s, c) => s + (c.product_count || 0), 0)}
                </div>
                <div style={{ fontSize: 12, color: 'var(--text3)' }}>Total Products</div>
              </div>
              <div className="card" style={{ flex: 1, textAlign: 'center' }}>
                <div style={{ fontSize: 28, fontFamily: 'Inter', fontWeight: 800, color: 'var(--orange)' }}>
                  {categories.filter(c => (c.product_count || 0) === 0).length}
                </div>
                <div style={{ fontSize: 12, color: 'var(--text3)' }}>Empty Categories</div>
              </div>
            </div>

            {/* Category cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 14 }}>
              {categories.map((cat, i) => (
                <div key={cat.id} className="card" style={{
                  display: 'flex', alignItems: 'flex-start', gap: 14, transition: 'border-color 0.2s',
                  borderColor: 'var(--border)',
                }}>
                  <div style={{
                    width: 50, height: 50, borderRadius: 12, flexShrink: 0,
                    background: CAT_COLORS[i % CAT_COLORS.length],
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 26
                  }}>
                    {CAT_EMOJIS[cat.name] || '📦'}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontFamily: 'Inter', fontWeight: 700, fontSize: 15, marginBottom: 2 }}>{cat.name}</div>
                    {cat.description && (
                      <div style={{ fontSize: 12, color: 'var(--text3)', marginBottom: 6, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {cat.description}
                      </div>
                    )}
                    <span className="badge badge-blue">{cat.product_count || 0} products</span>
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    <button className="btn btn-ghost btn-icon btn-sm"
                      onClick={() => { setSelected(cat); setModal(true); }} title="Edit">✏️</button>
                    <button className="btn btn-danger btn-icon btn-sm"
                      onClick={() => handleDelete(cat)} title="Delete">🗑️</button>
                  </div>
                </div>
              ))}
              {/* Add new button card */}
              <div className="card" style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                cursor: 'pointer', border: '1px dashed var(--border)', minHeight: 90,
                color: 'var(--text3)', gap: 8, fontSize: 14, fontWeight: 600,
                transition: 'all 0.15s'
              }} onClick={() => { setSelected(null); setModal(true); }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent)'; e.currentTarget.style.color = 'var(--accent)'; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.color = 'var(--text3)'; }}>
                <span style={{ fontSize: 22 }}>+</span> New Category
              </div>
            </div>

            {categories.length === 0 && (
              <div className="empty-state">
                <span className="icon">🗂️</span>
                <p>No categories yet. Add your first one!</p>
              </div>
            )}
          </>
        )}
      </div>

      {modal && (
        <CategoryModal category={selected}
          onSave={() => { setModal(false); fetchData(); }}
          onClose={() => setModal(false)} />
      )}
    </>
  );
}
